                    const linkPath = path.join(LINKS_DIR, `${cabinName}.obj`);
                    exportMeshesToSingleOBJ(cabinMeshes, linkPath);
                }
                console.log(`  Exported cabin sub-part: ${cabinName} (${cabinMeshes.length} meshes)`);
            }
        }
    }

    console.log('\nExport complete!');

    // Print summary
    const partMeshDirs = fs.readdirSync(PART_MESHES_DIR);
    console.log(`\nSummary:`);
    console.log(`  Part mesh directories: ${partMeshDirs.length}`);
    for (const dir of partMeshDirs) {
        const files = fs.readdirSync(path.join(PART_MESHES_DIR, dir));
        console.log(`    ${dir}/: ${files.length} mesh files`);
    }
    const linkFiles = fs.readdirSync(LINKS_DIR);
    console.log(`  Link files: ${linkFiles.length}`);
    for (const f of linkFiles) {
        console.log(`    ${f}`);
    }
}

main();

